@startuml

class Product {
  + name : string
  + description : string
  + net_price : double
}

class Manufacturer {
  + name : string
}

class Country {
  + name : string
  + vat_rate : float
  + currency : string
  + conversion_rate_to_euro : float
}

class Representative {
  + first_name : string
  + last_name : string
  + social_security_number : string
  + telephone_number : string
  + email_address : string
}

class Customer {
  + name : string
  + address : string
  + telephone_number : string
  + email_address : string
}

class Order {
  + order_id : string
  + quantity : int
  + order_date : date
  + desired_delivery_date : date
}

Manufacturer "1" -- "*" Product
Product "*" -- "*" Country
Representative "1" -- "1" Country
Customer "*" -- "*" Country
Representative "1" -- "*" Order
Order "*" -- "1" Product
Order "*" -- "1" Customer

@enduml

